parameters.jsCode:
// Normalises the metrics feed to the documented contract, or falls back to
// the bundled demo dataset so the template renders with zero external data.
//
// Contract (also in the sticky note + docs):
// { "period": "Jul 21-27", "company": "Acme",
//   "metrics": [ { "label": "MRR", "value": 48210, "unit": "$", "delta": 4.1, "lowerIsBetter": false,
//                  "history": [46311, 48210] } ] }
// `history` is OPTIONAL past values, oldest first, ending at `value` (the key
// `series` is accepted as an alias). Supply it and the metric scene draws a
// real sparkline of those numbers; leave it out and that scene draws NO chart
// at all - just the number and its delta. The video never draws a trend line
// for history it was not given.
const cfg = $('Config').first().json;

// Every number in here is invented (including the eight-week history arrays)
// - it is demo data, and every run that uses it is tagged usingDemoData: true.
const DEMO = {
  company: 'Acme',
  period: 'Jul 21-27',
  metrics: [
    { label: 'MRR', value: 48210, unit: '$', delta: 4.1, lowerIsBetter: false, history: [42980, 43610, 44520, 44210, 45380, 45990, 46311, 48210] },
    { label: 'New signups', value: 1284, unit: '', delta: 9.6, lowerIsBetter: false, history: [980, 1046, 1120, 1088, 1204, 1150, 1172, 1284] },
    { label: 'Weekly active users', value: 23417, unit: '', delta: 3.2, lowerIsBetter: false, history: [20140, 20890, 21430, 21280, 22050, 22410, 22691, 23417] },
    { label: 'Churn', value: 2.1, unit: '%', delta: -0.4, lowerIsBetter: true, history: [3.1, 2.9, 2.8, 2.9, 2.7, 2.6, 2.5, 2.1] },
    { label: 'NPS', value: 52, unit: '', delta: 8.7, lowerIsBetter: false, history: [41, 43, 44, 43, 46, 47, 48, 52] },
  ],
};

const CONTRACT = JSON.stringify({ period: 'Jul 21-27', company: 'Acme', metrics: [{ label: 'MRR', value: 48210, unit: '$', delta: 4.1, lowerIsBetter: false }] }, null, 2)
  + '\nOptional per metric: "history": [46311, 48210] - past values, oldest first, ending at value.'
  + '\nWith it that metric scene draws a real sparkline of those numbers; without it, no chart is drawn.';

const demo = (reason) => [{ json: { company: DEMO.company, period: DEMO.period, metrics: DEMO.metrics, usingDemoData: true, demoReason: reason } }];

const url = String(cfg.metricsUrl || '').trim();
if (!url) return demo('metricsUrl is empty');

const res = $input.first().json;
const status = Number(res.statusCode);
// Unreachable endpoint or an HTTP error -> demo data keeps the schedule alive.
if (!Number.isFinite(status) || status === 0) return demo('the metrics endpoint was unreachable');
if (status !== 200) return demo('the metrics endpoint answered HTTP ' + status);

// A configured endpoint that answered 200 with junk is a bug in YOUR data
// pipeline -> fail loudly with the exact contract instead of quietly
// rendering demo numbers that look real.
let body = res.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) {
    throw new Error('The metrics endpoint returned 200 but not JSON. Expected exactly this shape:\n' + CONTRACT);
  }
}
if (Array.isArray(body)) body = body[0];
if (!body || typeof body !== 'object' || !Array.isArray(body.metrics) || !body.metrics.length) {
  throw new Error('The metrics endpoint returned 200 but no metrics[] array. Expected exactly this shape:\n' + CONTRACT);
}

const problems = [];
const metrics = body.metrics.slice(0, 5).map(function (m, i) {
  const label = String((m && m.label) || '').trim();
  if (!label) problems.push('metrics[' + i + '].label is missing');
  const value = m && (typeof m.value === 'number' || typeof m.value === 'string') ? m.value : null;
  if (value === null || value === '') problems.push('metrics[' + i + '].value must be a number or a string');
  const delta = m && m.delta != null && m.delta !== '' && Number.isFinite(Number(m.delta)) ? Number(m.delta) : null;
  // Optional real history (`series` accepted as an alias). A malformed array
  // is a bug in YOUR pipeline, so it fails loudly rather than quietly drawing
  // a chart of the wrong numbers - or none where you expected one.
  const raw = m && m.history != null ? m.history : m && m.series != null ? m.series : null;
  const key = m && m.history != null ? 'history' : 'series';
  let history = null;
  if (raw != null) {
    if (!Array.isArray(raw)) problems.push('metrics[' + i + '].' + key + ' must be an array of numbers (or omitted)');
    else if (raw.some(function (p) { return !Number.isFinite(Number(p)); })) problems.push('metrics[' + i + '].' + key + ' must contain only numbers');
    else if (raw.length < 2) problems.push('metrics[' + i + '].' + key + ' needs at least 2 points (or omit it - that metric then renders with no chart)');
    else history = raw.map(Number).slice(-24);
  }
  const out = { label: label, value: value, unit: String((m && m.unit) || '').trim(), delta: delta, lowerIsBetter: Boolean(m && m.lowerIsBetter) };
  if (history) out.history = history;
  return out;
});
if (problems.length) {
  throw new Error('The metrics JSON does not match the contract:\n  - ' + problems.join('\n  - ') + '\nExpected exactly this shape:\n' + CONTRACT);
}

return [{ json: {
  company: String(body.company || '').trim(),
  period: String(body.period || '').trim(),
  metrics: metrics,
  usingDemoData: false,
  demoReason: null,
} }];

// Two jobs: (1) the music guard — a render must NEVER fail because a
// nice-to-have music bed is unreachable or oversized (the renderer rejects
// audio assets over the plan cap, which would fail the WHOLE render);
// (2) build the narration prompt so the Write narration HTTP node stays
// readable.
const cfg = $('Config').first().json;
const prepared = $('Prepare metrics').first().json;
const probe = $input.first().json;

let music = null;
let musicNote = 'no music bed configured';
const src = String(cfg.musicUrl || '').trim();
if (src) {
  const status = Number(probe.statusCode);
  const headers = probe.headers || {};
  const bytes = Number(headers['content-length'] || headers['Content-Length'] || 0);
  const limit = Number(cfg.maxMusicBytes ?? 5242880);
  if (status === 200 && (!bytes || bytes <= limit)) {
    music = { src: src };
    musicNote = 'ok' + (bytes ? ' (' + bytes + ' bytes)' : '');
  } else if (status !== 200) {
    musicNote = 'skipped: HEAD answered ' + (Number.isFinite(status) && status ? 'HTTP ' + status : 'nothing (unreachable)');
  } else {
    musicNote = 'skipped: ' + bytes + ' bytes exceeds maxMusicBytes (' + limit + ')';
  }
}

// ---- narration prompt ---------------------------------------------------
// The prompt spells out direction AND goodness per metric (lowerIsBetter is
// resolved HERE), so the model never has to reason about whether a falling
// churn number is good news.
const fmtValue = function (m) {
  if (typeof m.value === 'string') return m.value;
  const n = Number(m.value);
  const s = Math.abs(n) >= 1000 ? n.toLocaleString('en-US') : String(n);
  if (m.unit === '$') return s + ' dollars';
  if (m.unit === '%') return s + ' percent';
  return m.unit ? s + ' ' + m.unit : s;
};
const lines = prepared.metrics.map(function (m, i) {
  let move = 'unchanged vs last week';
  if (m.delta != null && m.delta !== 0) {
    const dir = m.delta > 0 ? 'up ' : 'down ';
    const good = m.lowerIsBetter ? m.delta < 0 : m.delta > 0;
    move = dir + Math.abs(m.delta) + ' percent vs last week - ' + (good ? 'an improvement' : 'a setback') + (m.lowerIsBetter ? ' (lower is better for this metric)' : '');
  }
  return (i + 1) + '. ' + m.label + ': ' + fmtValue(m) + ', ' + move + '.';
});

const promptText = 'Write the voice-over for a weekly KPI report video.\n' +
  'Company: ' + (prepared.company || cfg.brandName || 'the company') + '\n' +
  'Period: ' + (prepared.period || 'this week') + '\n' +
  'The metrics, in order:\n' + lines.join('\n') + '\n\n' +
  'Rules:\n' +
  '1. Return STRICT JSON only, exactly this shape: {"opening": "one sentence", "perMetric": ["one sentence per metric, in order"], "closing": "one sentence"}.\n' +
  '2. perMetric must contain exactly ' + prepared.metrics.length + ' sentences, one per metric, in the same order as the list above.\n' +
  '3. Calm, confident analyst tone. Plain spoken English. No hype, no greetings, no sign-off.\n' +
  '4. Spell every number out as words and round conversationally: say about forty eight thousand dollars, never 48210 or a currency symbol. Never use digits, percent signs or abbreviations - captions are aligned word by word to your text.\n' +
  '5. Plain ASCII punctuation only. No curly quotes, em dashes, emoji or markdown.\n' +
  '6. The opening names the company and the week. The closing sums the week up in one line.\n' +
  '7. Each perMetric sentence names the metric, its rounded value and the direction of the move; when a fall is a good thing (churn, backlog, spend) say so naturally.';

return [{ json: Object.assign({}, prepared, { music: music, musicNote: musicNote, promptText: promptText }) }];

// Parses the writer's JSON, normalises it to ASCII and checks it maps 1:1
// to the metrics. Everything downstream reads this node.
const res = $input.first().json;
const prepared = $('Music guard').first().json;

const content = res && res.choices && res.choices[0] && res.choices[0].message ? res.choices[0].message.content : null;
if (!content) {
  throw new Error('The model returned no content: ' + JSON.stringify(res).slice(0, 400));
}

let script;
try {
  script = JSON.parse(content);
} catch (e) {
  const m = /\{[\s\S]*\}/.exec(content);
  if (!m) throw new Error('The model did not return JSON:\n' + content.slice(0, 400));
  script = JSON.parse(m[0]);
}

// Models slip curly quotes and dashes in even when told not to, and unusual
// characters make the voice stumble. Normalise to ASCII before anything
// counts words or reaches the synthesiser.
const toAscii = function (s) {
  return String(s)
    .replace(/[\u2018\u2019\u02BC]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2013\u2014]/g, '-')
    .replace(/\u2026/g, '...')
    .replace(/\s+/g, ' ')
    .trim();
};

const opening = toAscii(script.opening || '');
const closing = toAscii(script.closing || '');
let perMetric = Array.isArray(script.perMetric) ? script.perMetric.map(toAscii).filter(Boolean) : [];
const expected = prepared.metrics.length;
if (!opening) throw new Error('The narration JSON has no opening sentence.');
if (!closing) throw new Error('The narration JSON has no closing sentence.');
if (perMetric.length > expected) perMetric = perMetric.slice(0, expected);
if (perMetric.length !== expected) {
  throw new Error('The model wrote ' + perMetric.length + ' metric sentences for ' + expected + ' metrics. Run it again, or set a stronger llmModel in Config.');
}

const narration = [opening].concat(perMetric, [closing]).join(' ');
const wordCount = narration.split(/\s+/).filter(Boolean).length;
if (wordCount < 25) {
  throw new Error('The narration is only ' + wordCount + ' words - too short to carry the video. Run it again, or set a stronger llmModel.');
}

return [{ json: { opening: opening, perMetric: perMetric, closing: closing, narration: narration, wordCount: wordCount } }];

// Turns one ElevenLabs "with-timestamps" response into (a) an mp3 binary ready
// for upload and (b) word timings.
//
// The alignment comes from the synthesiser itself, so the timings ARE the audio
// — there is no separate transcription step to disagree with, and nothing that
// can drift. That is the whole reason this endpoint is used instead of plain
// text-to-speech.
const res = $input.first().json;

if (!res || !res.audio_base64) {
  throw new Error(
    'ElevenLabs returned no audio. Check the xi-api-key credential, the voiceId, and your character quota. Response: ' +
      JSON.stringify(res).slice(0, 300)
  );
}

const a = res.alignment || res.normalized_alignment;
if (!a || !Array.isArray(a.characters)) {
  throw new Error('ElevenLabs returned audio but no alignment — make sure the URL ends in /with-timestamps.');
}

const chars = a.characters;
const starts = a.character_start_times_seconds || [];
const ends = a.character_end_times_seconds || [];

// Alignment is per CHARACTER; group runs of non-whitespace into words.
const words = [];
let cur = null;
for (let i = 0; i < chars.length; i += 1) {
  const ch = chars[i];
  if (/\s/.test(ch)) {
    if (cur) { words.push(cur); cur = null; }
    continue;
  }
  if (!cur) cur = { text: ch, start: Number(starts[i]), end: Number(ends[i]) };
  else { cur.text += ch; cur.end = Number(ends[i]); }
}
if (cur) words.push(cur);

if (!words.length) throw new Error('Alignment contained no words.');

const duration = Number(ends[ends.length - 1]) || words[words.length - 1].end;

return [{
  json: { words, duration, wordCount: words.length },
  // n8n binary payloads carry base64 in `data`; naming it matters because Zvid
  // derives the media kind from the MIME type on upload.
  binary: {
    data: {
      data: res.audio_base64,
      mimeType: 'audio/mpeg',
      fileName: 'voiceover.mp3',
      fileExtension: 'mp3',
    },
  },
}];

// === buildProject — identical to the frame-reviewed standalone builder ===
// Turns one week of KPI data (up to five metrics) into a 1920x1080 report
// video: branded title card, one scene per metric, then a summary grid. Works
// BOTH with a narrated voiceover (word-timed cuts + karaoke captions) and
// without one (music only, fixed scene lengths) — `narration` is null on the
// narrate:false path.
//
// THE ONE RULE THIS FILE EXISTS TO ENFORCE: a chart is drawn only from numbers
// the caller actually sent. A metric with a real `history` array (optional, per
// the documented contract) gets a sparkline of THOSE values. A metric without
// one gets NO chart at all — the card becomes a centred number + delta pill.
// There is no synthetic, decorative or "illustrative" trend line anywhere.
function buildProject(config, source, narration) {
  const cfg = config || {};
  const clean = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const round = (n) => Math.round(n * 100) / 100;
  const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));

  // ---- palette ------------------------------------------------------------
  const safeHex = (v, fallback) => (/^#[0-9a-fA-F]{6}$/.test(clean(v)) ? clean(v) : fallback);
  const accent = safeHex(cfg.brandAccent, '#38E1FF');
  const bg = safeHex(cfg.brandBackground, '#0B1220');
  const ink = safeHex(cfg.textColor, '#FFFFFF');
  const muted = safeHex(cfg.mutedColor, '#9DB0CC');
  const good = safeHex(cfg.goodColor, '#34D399');
  const bad = safeHex(cfg.badColor, '#FF6B78');
  const font = clean(cfg.font) || 'Space Grotesk';
  const hexToRgb = (h) => { const n = parseInt(h.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; };
  const rgba = (h, a) => { const [r, g, b] = hexToRgb(h); return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')'; };
  // A slightly lifted card-interior tone derived from the background.
  const lift = (h, amt) => { const [r, g, b] = hexToRgb(h); const f = (x) => Math.min(255, Math.round(x + amt)); return 'rgb(' + f(r) + ',' + f(g) + ',' + f(b) + ')'; };

  // ---- data ---------------------------------------------------------------
  const company = clean(source.company) || clean(cfg.brandName) || 'Your company';
  const period = clean(source.period) || 'This week';
  const rawMetrics = (Array.isArray(source.metrics) ? source.metrics : []).slice(0, 5);
  if (!rawMetrics.length) throw new Error('No metrics to render — Prepare metrics produced an empty list.');

  const fmtValue = (m) => {
    if (typeof m.value === 'string') return clean(m.value);
    const n = Number(m.value);
    if (!Number.isFinite(n)) return clean(String(m.value));
    const s = Math.abs(n) >= 1000 ? n.toLocaleString('en-US') : String(n);
    const unit = clean(m.unit);
    if (unit === '$') return '$' + s;
    if (unit === '%') return s + '%';
    return unit ? s + ' ' + unit : s;
  };
  const fmtDelta = (d) => {
    const a = Math.round(Math.abs(d) * 10) / 10;
    return String(a) + '%';
  };

  const items = rawMetrics.map((m, i) => {
    const label = clean(m.label) || 'Metric ' + (i + 1);
    const valueText = fmtValue(m);
    const deltaNum = m.delta == null || m.delta === '' ? null : Number(m.delta);
    const hasDelta = deltaNum != null && Number.isFinite(deltaNum);
    const lowerIsBetter = Boolean(m.lowerIsBetter);
    const dir = !hasDelta || deltaNum === 0 ? 0 : deltaNum > 0 ? 1 : -1;
    // churn DOWN is green: goodness respects lowerIsBetter, arrows respect the sign.
    const improving = dir === 0 ? null : lowerIsBetter ? dir < 0 : dir > 0;
    const chipColor = dir === 0 || !hasDelta ? muted : improving ? good : bad;
    const arrow = dir > 0 ? '▲' : dir < 0 ? '▼' : '';
    const chipText = !hasDelta ? '' : dir === 0 ? 'flat vs last week' : arrow + ' ' + fmtDelta(deltaNum) + ' vs last week';
    // `history` is OPTIONAL real past values (`series` is accepted as an alias).
    // Only a genuine array of at least two finite numbers becomes a chart;
    // anything else means no chart exists, so none is drawn.
    const raw = Array.isArray(m.history) ? m.history : Array.isArray(m.series) ? m.series : null;
    const nums = raw ? raw.map(Number).filter((x) => Number.isFinite(x)) : [];
    const history = raw && nums.length >= 2 && nums.length === raw.length ? nums.slice(-24) : null;
    return { label, valueText, deltaNum, hasDelta, lowerIsBetter, dir, improving, chipColor, chipText, history };
  });

  // ---- trend panel --------------------------------------------------------
  // NOTHING here is invented. Exactly two states:
  //   * `history` supplied (>= 2 real numbers) -> a sparkline of THOSE numbers,
  //     labelled with how many periods it covers. Gridlines, area fill and the
  //     end-point dot are earned here because the shape is real data.
  //   * no `history` -> NO panel and no divider rule at all, whether or not a
  //     delta exists. The card switches to the centred number + delta layout
  //     below. Nothing on screen stands in for history that was not supplied.
  const PX0 = 1190; const PX1 = 1700; const PYT = 400; const PYB = 720;

  const historySvg = (it) => {
    const s = it.history;
    const n = s.length;
    const lo = Math.min.apply(null, s);
    const hi = Math.max.apply(null, s);
    const span = hi - lo;
    const pts = s.map((v, i) => {
      const t = i / (n - 1);
      const norm = span === 0 ? 0.5 : clamp(0.08 + ((v - lo) / span) * 0.84, 0.08, 0.92);
      return [round(PX0 + t * (PX1 - PX0)), round(PYB - norm * (PYB - PYT))];
    });
    const line = pts.map((p) => p[0] + ',' + p[1]).join(' ');
    const area = line + ' ' + PX1 + ',' + PYB + ' ' + PX0 + ',' + PYB;
    const last = pts[n - 1];
    const grid = [PYT, Math.round((PYT + PYB) / 2), PYB]
      .map((y) => "<line x1='" + PX0 + "' y1='" + y + "' x2='" + PX1 + "' y2='" + y + "' stroke='rgba(255,255,255,0.08)' stroke-width='1.5'/>")
      .join('');
    return grid +
      "<polygon points='" + area + "' fill='" + rgba(it.chipColor, 0.12) + "'/>" +
      "<polyline points='" + line + "' fill='none' stroke='" + it.chipColor + "' stroke-width='5' stroke-linecap='round' stroke-linejoin='round'/>" +
      "<circle cx='" + last[0] + "' cy='" + last[1] + "' r='14' fill='" + rgba(it.chipColor, 0.25) + "'/>" +
      "<circle cx='" + last[0] + "' cy='" + last[1] + "' r='7' fill='" + it.chipColor + "'/>";
  };

  const hasPanel = (it) => Boolean(it.history);
  const panelSvg = (it) => "<svg width='1920' height='1080' viewBox='0 0 1920 1080' xmlns='http://www.w3.org/2000/svg'>" + historySvg(it) + '</svg>';
  const panelLabel = (it) => 'TREND &middot; LAST ' + it.history.length + ' PERIODS';

  // ---- narration timing ---------------------------------------------------
  const narrated = Boolean(narration && narration.parsed && narration.timings && narration.voUrl);
  const tailSeconds = Number(cfg.tailSeconds ?? 0.6);
  const transition = clean(cfg.sceneTransition) || null;
  const tDur = transition ? Number(cfg.transitionSeconds ?? 0.45) : 0;

  let spans = null;            // visible [start,end] per scene: title, metrics..., summary
  let words = [];
  let cutsAlignedToSpeech = false;
  let audioDuration = 0;

  if (narrated) {
    words = (Array.isArray(narration.timings.words) ? narration.timings.words : [])
      .map((w) => ({ text: String(w.text == null ? '' : w.text).trim(), start: Number(w.start), end: Number(w.end) }))
      .filter((w) => w.text && Number.isFinite(w.start) && Number.isFinite(w.end));
    const narrationEnd = words.length ? words[words.length - 1].end : Number(narration.timings.duration) || 30;
    audioDuration = Math.max(Number(narration.timings.duration) || 0, narrationEnd);

    const countWords = (s) =>
      String(s || '').replace(/[^\p{L}\p{N}'\u2019]+/gu, ' ').trim().split(/\s+/).filter(Boolean).length;
    const segments = [narration.parsed.opening].concat(narration.parsed.perMetric, [narration.parsed.closing]);
    const segWords = segments.map(countWords);
    const totalScripted = segWords.reduce((a, b) => a + b, 0);

    // The alignment covers the exact text that was spoken, so walking the word
    // stream by per-segment word count puts every cut on a sentence boundary.
    // If the tokenisation drifts, fall back to a proportional split so the
    // render can never desync.
    const drift = totalScripted ? Math.abs(words.length - totalScripted) / totalScripted : 1;
    cutsAlignedToSpeech = words.length > 0 && drift <= 0.2;

    spans = [];
    if (cutsAlignedToSpeech) {
      let cursor = 0;
      for (let i = 0; i < segWords.length; i += 1) {
        const start = cursor === 0 ? 0 : words[cursor - 1].end;
        cursor = Math.min(cursor + segWords[i], words.length);
        const last = words[cursor - 1];
        spans.push({ start, end: i === segWords.length - 1 ? audioDuration : last ? last.end : audioDuration });
      }
    } else {
      const weightTotal = totalScripted || segWords.length;
      let t = 0;
      for (let i = 0; i < segWords.length; i += 1) {
        const start = t;
        t = i === segWords.length - 1 ? audioDuration : t + ((segWords[i] || 1) / weightTotal) * audioDuration;
        spans.push({ start, end: t });
      }
    }
    spans[spans.length - 1].end += tailSeconds;
  } else {
    // Music-only pacing: the on-screen numbers carry the video.
    let t = 0;
    spans = [];
    const fixed = [4.2].concat(items.map(() => 3.6), [5.4]);
    for (const d of fixed) { spans.push({ start: t, end: t + d }); t += d; }
  }

  const sceneCount = items.length + 2;
  const minScene = Math.max(1.4, tDur * 3);
  const visibleFor = (i) => Math.max(minScene, round(spans[i].end - spans[i].start));

  // ---- shared scene chrome ------------------------------------------------
  const frameStroke = rgba(accent, 0.28);
  const metaLine = esc(company.toUpperCase()) + ' &middot; ' + esc(period.toUpperCase());

  const scenes = [];
  const transitionFor = (i) => (i === sceneCount - 2 ? 'smoothup' : transition);

  // ---- scene 1: title card ------------------------------------------------
  {
    const i = 0;
    const visible = visibleFor(i);
    const dur = round(visible + (sceneCount > 1 ? tDur : 0));
    const kicker = clean(cfg.reportKicker) || 'WEEKLY KPI REPORT';
    const title = clean(cfg.reportTitle) || 'The week in numbers.';
    const titleSize = title.length <= 26 ? 112 : title.length <= 40 ? 88 : 68;
    const heroVideo = clean(cfg.titleVideoUrl);
    const visuals = [];
    if (heroVideo) {
      visuals.push({ type: 'VIDEO', src: heroVideo, width: 1920, height: 1080, position: 'center-center', resize: 'cover', volume: 0, zoom: { depth: 1.06 }, track: 0, enterBegin: 0, exitEnd: dur });
    }
    visuals.push({
      type: 'SVG', width: 1920, height: 1080, track: 1, enterBegin: 0, exitEnd: dur,
      svg: "<svg width='1920' height='1080' viewBox='0 0 1920 1080' xmlns='http://www.w3.org/2000/svg'><defs><linearGradient id='krIntro' x1='0' y1='0' x2='1' y2='0'><stop offset='0' stop-color='" + bg + "' stop-opacity='0.97'/><stop offset='0.55' stop-color='" + bg + "' stop-opacity='0.78'/><stop offset='1' stop-color='" + bg + "' stop-opacity='0.4'/></linearGradient></defs><rect width='1920' height='1080' fill='url(#krIntro)'/><rect x='110' y='150' width='1700' height='780' rx='34' fill='none' stroke='" + rgba(accent, 0.18) + "' stroke-width='1.5'/><path d='M130 700 H370' stroke='" + accent + "' stroke-width='6' stroke-linecap='round'/></svg>",
    });
    visuals.push({
      type: 'TEXT', x: 130, y: 250, width: 1250, anchor: 'top-left', track: 2, enterBegin: 0.25, enterEnd: 0.75, enterAnimation: 'smoothup', exitEnd: dur,
      style: { fontFamily: font, color: ink },
      html: "<div style='color:" + accent + "; font-size:27px; font-weight:700; letter-spacing:7px;'>" + esc(kicker) + "</div><div style='margin-top:26px; color:" + ink + "; font-size:" + titleSize + "px; line-height:1.02; font-weight:700; letter-spacing:-3px;'>" + esc(title) + '</div>',
    });
    visuals.push({
      type: 'TEXT', x: 130, y: 770, anchor: 'top-left', track: 3, enterBegin: 0.6, enterEnd: 1.1, enterAnimation: 'fade', exitEnd: dur,
      style: { fontFamily: font, color: ink },
      html: "<div style='color:" + ink + "; font-size:31px; font-weight:700; letter-spacing:2px;'>" + esc(company) + "<span style='color:" + rgba(muted, 0.85) + "; font-weight:500;'>&nbsp;&nbsp;&middot;&nbsp;&nbsp;" + esc(period) + '</span></div>',
    });
    scenes.push({
      id: 'title', duration: dur, backgroundColor: bg,
      ...(transitionFor(0) ? { transition: transitionFor(0), transitionDuration: tDur } : {}),
      visuals,
    });
  }

  // ---- one scene per metric ----------------------------------------------
  items.forEach((it, idx) => {
    const i = idx + 1;
    const visible = visibleFor(i);
    const isLast = i === sceneCount - 1; // never true here (summary follows)
    const dur = round(visible + (isLast ? 0 : tDur));
    const vLen = it.valueText.length;
    const valueSize = vLen <= 6 ? 184 : vLen <= 8 ? 158 : vLen <= 10 ? 134 : vLen <= 13 ? 110 : 88;
    const panel = hasPanel(it);
    const align = panel ? 'left' : 'center';
    const chipHtml = it.hasDelta
      ? "<div style='margin-top:32px; text-align:" + align + ";'><span style='display:inline-block; background:" + rgba(it.chipColor, 0.13) + '; border:1.5px solid ' + rgba(it.chipColor, 0.5) + '; color:' + it.chipColor + "; border-radius:999px; padding:12px 30px; font-size:29px; font-weight:700;'>" + esc(it.chipText) + '</span></div>'
      : '';
    const hintHtml = it.lowerIsBetter && it.hasDelta
      ? "<div style='margin-top:22px; text-align:" + align + '; color:' + rgba(muted, 0.8) + "; font-size:24px; font-weight:500;'>Lower is better for this one.</div>"
      : '';
    // No history -> no chart. The card becomes ONE centred column (accent rule,
    // label, number, delta pill) optically centred in the card frame (150..930)
    // rather than a left column staring at the empty half where a chart would
    // have gone. Heights below are the type metrics of the block above.
    const ruleHtml = panel ? '' : "<div style='width:120px; height:5px; border-radius:3px; background:" + accent + "; margin:0 auto 34px;'></div>";
    const blockH = 38 + 22 + Math.round(valueSize * 1.02) + (it.hasDelta ? 96 : 0) + (hintHtml ? 52 : 0) + (panel ? 0 : 39);
    const blockY = panel ? 330 : clamp(Math.round(540 - blockH / 2), 250, 470);
    const visuals = [
      {
        type: 'SVG', width: 1920, height: 1080, track: 0, enterBegin: 0, exitEnd: dur,
        svg: "<svg width='1920' height='1080' viewBox='0 0 1920 1080' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='krCard" + idx + "' cx='0.3' cy='0.35' r='0.95'><stop offset='0' stop-color='" + lift(bg, 14) + "'/><stop offset='1' stop-color='" + bg + "'/></radialGradient></defs><rect width='1920' height='1080' fill='url(#krCard" + idx + ")'/><rect x='120' y='150' width='1680' height='780' rx='40' fill='rgba(255,255,255,0.028)' stroke='" + frameStroke + "' stroke-width='1.5'/>" +
          (panel ? "<line x1='1120' y1='250' x2='1120' y2='830' stroke='rgba(255,255,255,0.08)' stroke-width='1.5'/>" : '') + '</svg>',
      },
      {
        type: 'TEXT', x: 210, y: 208, anchor: 'top-left', track: 2, enterBegin: 0, exitEnd: dur,
        style: { fontFamily: font, color: ink },
        html: "<div style='color:" + rgba(muted, 0.75) + "; font-size:22px; font-weight:700; letter-spacing:4px;'>" + metaLine + '</div>',
      },
      {
        type: 'TEXT', x: 1710, y: 208, anchor: 'top-right', track: 3, enterBegin: 0, exitEnd: dur,
        style: { fontFamily: font, color: ink },
        html: "<div style='color:" + rgba(muted, 0.6) + "; font-size:22px; font-weight:700; letter-spacing:4px; text-align:right;'>0" + (idx + 1) + ' / 0' + items.length + '</div>',
      },
      {
        type: 'TEXT',
        x: panel ? 210 : 960, y: blockY, width: panel ? 860 : 1500,
        anchor: panel ? 'top-left' : 'top-center',
        track: 4, enterBegin: 0.25, enterEnd: 0.7, enterAnimation: 'smoothup', exitEnd: dur,
        style: { fontFamily: font, color: ink },
        html: ruleHtml + "<div style='text-align:" + align + '; color:' + rgba(muted, 0.95) + "; font-size:30px; font-weight:700; letter-spacing:5px;'>" + esc(it.label.toUpperCase()) + "</div><div style='text-align:" + align + '; margin-top:22px; color:' + ink + '; font-size:' + valueSize + "px; line-height:0.95; font-weight:700; letter-spacing:-5px;'>" + esc(it.valueText) + '</div>' + chipHtml + hintHtml,
      },
    ];
    if (panel) {
      visuals.push({
        type: 'SVG', width: 1920, height: 1080, track: 1, enterBegin: 0.45, enterEnd: 0.95, enterAnimation: 'fade', exitEnd: dur,
        svg: panelSvg(it),
      });
      visuals.push({
        type: 'TEXT', x: PX0, y: 334, anchor: 'top-left', track: 5, enterBegin: 0.45, enterEnd: 0.95, enterAnimation: 'fade', exitEnd: dur,
        style: { fontFamily: font, color: ink },
        html: "<div style='color:" + rgba(muted, 0.65) + "; font-size:22px; font-weight:700; letter-spacing:4px;'>" + panelLabel(it) + '</div>',
      });
    }
    scenes.push({
      id: 'metric-' + (idx + 1), duration: dur, backgroundColor: bg,
      ...(transitionFor(i) ? { transition: transitionFor(i), transitionDuration: tDur } : {}),
      visuals,
    });
  });

  // ---- summary grid -------------------------------------------------------
  let narratedClosingUsed = false;
  {
    const i = sceneCount - 1;
    const visible = visibleFor(i);
    const dur = round(visible); // last scene: no transition pad
    const n = items.length;
    const cardW = 520; const cardH = 240;
    let slots;
    // Every row is centred on 960: 3-up spans 120..1800, 2-up spans 410..1510.
    if (n === 5) slots = [[120, 310], [700, 310], [1280, 310], [410, 590], [990, 590]];
    else if (n === 4) slots = [[410, 310], [990, 310], [410, 590], [990, 590]];
    else if (n === 3) slots = [[120, 400], [700, 400], [1280, 400]];
    else if (n === 2) slots = [[410, 400], [990, 400]];
    else slots = [[700, 400]];
    const gridBottom = slots.reduce((m, s) => Math.max(m, s[1] + cardH), 0);

    const cardsSvg = slots.map((s) =>
      "<rect x='" + s[0] + "' y='" + s[1] + "' width='" + cardW + "' height='" + cardH + "' rx='26' fill='rgba(255,255,255,0.03)' stroke='" + frameStroke + "' stroke-width='1.5'/><rect x='" + s[0] + "' y='" + s[1] + "' width='" + cardW + "' height='5' rx='2.5' fill='" + accent + "'/>").join('');

    const visuals = [
      {
        type: 'SVG', width: 1920, height: 1080, track: 0, enterBegin: 0, exitEnd: dur,
        svg: "<svg width='1920' height='1080' viewBox='0 0 1920 1080' xmlns='http://www.w3.org/2000/svg'><defs><radialGradient id='krSum' cx='0.5' cy='0.25' r='1'><stop offset='0' stop-color='" + lift(bg, 12) + "'/><stop offset='1' stop-color='" + bg + "'/></radialGradient></defs><rect width='1920' height='1080' fill='url(#krSum)'/>" + cardsSvg + '</svg>',
      },
      {
        type: 'TEXT', x: 960, y: 170, anchor: 'top-center', track: 1, enterBegin: 0.2, enterEnd: 0.6, enterAnimation: 'smoothdown', exitEnd: dur,
        style: { fontFamily: font, color: ink },
        html: "<div style='text-align:center; color:" + rgba(muted, 0.9) + "; font-size:26px; font-weight:700; letter-spacing:6px;'>THE WEEK AT A GLANCE &middot; " + esc(period.toUpperCase()) + '</div>',
      },
    ];

    items.forEach((it, idx) => {
      const s = slots[idx];
      const vLen = it.valueText.length;
      const vSize = vLen <= 7 ? 64 : vLen <= 10 ? 54 : vLen <= 13 ? 46 : 38;
      const chip = it.hasDelta
        ? "<div style='margin-top:16px; color:" + it.chipColor + "; font-size:24px; font-weight:700;'>" + (it.dir === 0 ? 'flat' : (it.dir > 0 ? '▲ ' : '▼ ') + fmtDelta(it.deltaNum)) + '</div>'
        : '';
      visuals.push({
        type: 'TEXT', x: s[0] + 40, y: s[1] + 44, width: cardW - 80, anchor: 'top-left', track: 2 + idx,
        enterBegin: round(0.35 + idx * 0.12), enterEnd: round(0.75 + idx * 0.12), enterAnimation: 'smoothup', exitEnd: dur,
        style: { fontFamily: font, color: ink },
        html: "<div style='color:" + rgba(muted, 0.85) + "; font-size:20px; font-weight:700; letter-spacing:2px;'>" + esc(it.label.toUpperCase()) + "</div><div style='margin-top:14px; color:" + ink + '; font-size:' + vSize + "px; line-height:1; font-weight:700; letter-spacing:-2px;'>" + esc(it.valueText) + '</div>' + chip,
      });
    });

    // The analyst's actual take closes the video: on a narrated run this is the
    // LLM's own `closing` sentence (the one the voice-over just spoke), so the
    // last frame agrees with the audio instead of a fixed boilerplate line.
    // Without narration there is no closing to use — Config.summaryLine carries it.
    const narratedClosing = narrated && narration.parsed ? clean(narration.parsed.closing) : '';
    narratedClosingUsed = Boolean(narratedClosing);
    const summaryLine = narratedClosing || clean(cfg.summaryLine) || 'Full breakdown in the dashboard.';
    const sSize = summaryLine.length <= 70 ? 30 : summaryLine.length <= 110 ? 26 : 23;
    visuals.push({
      type: 'TEXT', x: 960, y: Math.max(gridBottom + 40, 690), width: 1400, anchor: 'top-center', track: 7, enterBegin: 0.9, enterEnd: 1.3, enterAnimation: 'fade', exitEnd: dur,
      style: { fontFamily: font, color: ink },
      html: "<div style='text-align:center; color:" + rgba(muted, 0.95) + '; font-size:' + sSize + "px; line-height:1.4; font-weight:500;'>" + esc(summaryLine) + "</div><div style='margin-top:20px; text-align:center; color:" + rgba(muted, 0.55) + "; font-size:22px; font-weight:700; letter-spacing:4px;'>" + metaLine + '</div>',
    });

    scenes.push({ id: 'summary', duration: dur, backgroundColor: bg, visuals });
  }

  const totalDuration = round(scenes.reduce((sum, s) => sum + s.duration, 0) - tDur * Math.max(0, scenes.length - 1));

  // ---- captions (narrated runs only) --------------------------------------
  let subtitle;
  let captionCount = 0;
  if (narrated && words.length) {
    const perCue = Math.max(1, Number(cfg.captionWordsPerCue ?? 4));
    const captions = [];
    for (let w = 0; w < words.length; w += perCue) {
      const chunk = words.slice(w, w + perCue);
      captions.push({
        start: chunk[0].start,
        end: chunk[chunk.length - 1].end,
        text: chunk.map((x) => x.text).join(' '),
        words: chunk.map((x) => ({ start: x.start, end: x.end, text: x.text })),
      });
    }
    captionCount = captions.length;
    subtitle = {
      captions,
      animation: clean(cfg.captionAnimation) || 'karaoke',
      activeWord: { color: accent },
      font: { family: font, size: Number(cfg.captionSize ?? 40), color: '#FFFFFF', bold: true },
      stroke: { color: '#000000', width: Math.max(0, Number(cfg.captionStrokeWidth ?? 6)) },
      position: 'bottom',
      margin: { x: 260, y: 48 },
      maxWordsPerLine: perCue,
    };
  }

  // ---- audio --------------------------------------------------------------
  // NOTE: no `track` on audios — the render API rejects audios[].track.
  const audios = [];
  if (narrated) audios.push({ src: narration.voUrl, volume: 1 });
  const music = source.music && source.music.src ? source.music : null;
  if (music) audios.push({ src: music.src, volume: Number(narrated ? cfg.musicVolume ?? 0.12 : cfg.musicVolumeSolo ?? 0.26) });

  // The render API only allows letters, digits, spaces, _ and - in `name`.
  const safeName = ('kpi-report-' + company + '-' + period).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);

  const payload = {
    name: safeName || 'kpi-report',
    resolution: clean(cfg.resolution) || 'full-hd',
    frameRate: Number(cfg.frameRate ?? 30),
    backgroundColor: bg,
    outputFormat: 'mp4',
    scenes,
    ...(audios.length ? { audios } : {}),
    ...(subtitle ? { subtitle } : {}),
  };

  return {
    payload,
    meta: {
      company,
      period,
      metricCount: items.length,
      usingDemoData: Boolean(source.usingDemoData),
      narrated,
      narrationSeconds: narrated ? round(audioDuration) : 0,
      totalDuration,
      sceneCount: scenes.length,
      sceneDurations: scenes.map((s) => s.duration),
      captionCount,
      cutsAlignedToSpeech,
      musicUrl: music ? music.src : null,
      summaryLineSource: narratedClosingUsed ? 'narration closing' : 'Config.summaryLine',
      metrics: items.map((it) => ({
        label: it.label,
        value: it.valueText,
        chip: it.chipText || null,
        improving: it.improving,
        trendPanel: it.history ? 'sparkline of ' + it.history.length + ' real history points' : 'none (no history supplied)',
      })),
    },
  };
}

// === n8n glue ===
const config = $('Config').first().json;
const source = $('Music guard').first().json;

// The voiceover chain only runs when Config.narrate is true; referencing an
// unexecuted node throws, so the narrate:false path lands in the catch.
let narration = null;
try {
  const parsed = $('Parse narration').first().json;
  const timings = $('Voice + timings').first().json;
  const upload = $('Upload voiceover').first().json.upload;
  if (parsed && timings && upload && upload.url) {
    narration = { parsed, timings, voUrl: upload.url };
  }
} catch (e) { /* narrate: false — music-only video */ }

if (config.narrate && !narration) {
  throw new Error('narrate is true but the voiceover chain produced no usable audio. Check the OpenRouter and ElevenLabs credentials on Write narration / Generate voiceover, or set narrate: false in Config for a music-only video.');
}

const built = buildProject(config, source, narration);
return [{ json: built }];

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug — surface the field list instead of a
// generic HTTP error.
const res = $input.first().json;
const status = res.statusCode;
const body = res.body || {};

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
return [{
  json: {
    ...build,
    creditsRequired: body.creditsRequired,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: everything except the paid render. Open editorLink to preview the
// exact video, then set dryRun to false in Config to go live. Nothing is
// posted to Slack on a dry run.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the rest of the dry-run report.
let editorLink = null;
let draftId = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    company: d.meta.company,
    period: d.meta.period,
    metrics: d.meta.metrics,
    usingDemoData: d.meta.usingDemoData,
    narrated: d.meta.narrated,
    videoSeconds: d.meta.totalDuration,
    creditsRequired: d.creditsRequired,
    editorLink,
    draftId,
    warnings: d.warnings,
    slackPosted: false,
    nextStep: editorLink
      ? 'Open editorLink to preview the draft, then set dryRun to false in Config to render and post to Slack.'
      : 'Set dryRun to false in Config to render this for real.',
    payload: d.payload,
  },
}];

// Fails fast on a failed render and stops the poll loop from running forever.
const cfg = $('Config').first().json;
const job = $input.first().json;

if (job.state === 'failed') {
  throw new Error('Render failed: ' + (job.failedReason || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes (job ' + job.id + ', state ' + job.state + ').');
}

return $input.all();

// Final report for a live run. ONE item carrying videoUrl, so ▶ Watch video
// downloads exactly one MP4.
const cfg = $('Config').first().json;
const build = $('Check validation').first().json;
const job = $('Get render status').first().json;
const url = typeof job.result === 'string' ? job.result : (job.result ? job.result.url : null);

const slackConfigured = String(cfg.slackWebhookUrl || '').trim() !== '';
let slackAttempted = false;
try { $('Post to Slack').first(); slackAttempted = true; } catch (e) { /* Slack branch skipped */ }

return [{
  json: {
    rendered: true,
    videoUrl: url,
    jobId: job.id,
    company: build.meta.company,
    period: build.meta.period,
    metricCount: build.meta.metricCount,
    usingDemoData: build.meta.usingDemoData,
    narrated: build.meta.narrated,
    videoSeconds: build.meta.totalDuration,
    creditsCharged: build.creditsRequired,
    musicNote: $('Music guard').first().json.musicNote,
    slackConfigured,
    slackAttempted,
  },
}];
